import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The history of each sheet, for the as-of view. Every commit of a change on a sheet keeps all the
 * sheet's rows, in every table that belongs to it, against the sheet's today at that moment (see
 * {@link HistoryTransactionManager}); a later change on the same today replaces what was kept for it.
 * The sheet as it stood at the end of a date is what the last change made on a today on or before
 * that date left, and {@link #restore} puts the sheet back to it inside a transaction that is then
 * rolled back.
 *
 * <p>The tables that belong to a sheet are found from the schema: those with a {@code sheet_id}
 * column, and those whose rows reference the rows of such a table, so a table added later is kept
 * with no change here.
 */
@Service
public class SheetHistory {

    /** A body run while a request changes a sheet. */
    @FunctionalInterface
    public interface Body {
        void run() throws IOException, ServletException;
    }

    /** The sheet the current request changes, if it changes one. */
    private static final ThreadLocal<String> CHANGING = new ThreadLocal<>();

    private static final String SHEET = "SHEET";
    private static final Set<String> NOT_KEPT = Set.of("SHEET_HISTORY", "FLYWAY_SCHEMA_HISTORY");

    /** The rows of one table, as kept. */
    private record Rows(String table, String[] columns, List<Object[]> rows) implements Serializable {
    }

-- What each sheet held at the end of each of its todays, for the as-of view: after every change
-- the sheet's rows are kept against the today the change was made on (the latest change on that
-- today wins), numbered in the order the changes were made. Not referenced by, nor referencing, the
-- sheet's own tables, so it is never part of what it records.
CREATE SEQUENCE sheet_history_seq;
CREATE TABLE sheet_history (
    sheet_id  VARCHAR(100) NOT NULL,
    today     DATE         NOT NULL,
    seq       BIGINT       NOT NULL,
    rows_data BLOB         NOT NULL,
    PRIMARY KEY (sheet_id, today)
);
CREATE INDEX sheet_history_seq_order ON sheet_history (sheet_id, seq);
